    if (compressed_size <= 0) return NULL;

    // Allocate maximum possible size (worst case: each byte expands to 255 bytes)
    unsigned char* result = malloc(255 * compressed_size);
    if (!result) return NULL;

    int out_idx = 0;
    for (int i = 0; i < compressed_size; i += 2) {
        if (i + 1 < compressed_size) {
            unsigned char count = compressed_data[i];
            unsigned char value = compressed_data[i + 1];

            for (int j = 0; j < count && out_idx < 255 * compressed_size; j++) {
                result[out_idx++] = value;
            }
        }
    }

    *decompressed_size = out_idx;
    return result;
}

